INSERT INTO feature VALUES('glf-two-views','descriptions','GLF: the two views of a signature','levitated-descriptions','implemented','uncommon','dependent provers','The first-order model generated from a signature code by the single-substitution fold, each source equation read in it: a binding field as its body in the context its port extends, its variable as `$q` under `$p`, and a metavariable''s instantiation `t(u)` as the substitution operator, `$sub(t, $single(u))`; one generic evaluation and readback for every simply-sorted signature, identified with the first-order view on three signatures; the identity-return model''s judgements admitted by the kernel. A source cannot yet name the model it generates (#2422).','theory-levitation','crates/theory-levitation/tests/glf.rs','crate-tests','#640 #2422');
